-- Структура форума под World RP: разделы организаций (устав, заявления, жалобы на сотрудников),
-- законодательная база, восстановление имущества, новые префиксы, новая анкета техподдержки.
-- Повторный запуск безопасен: INSERT IGNORE по явным id.




-- Анкета техподдержки: способ входа (лаунчер / клиент) и тип проблемы
UPDATE nodes SET form_json = '{"title": "{kind} | {problem}", "fields": [{"key": "nick", "label": "Ваш игровой ник", "type": "text", "required": true, "placeholder": "Имя_Фамилия", "max": 32}, {"key": "kind", "label": "Что случилось", "type": "select", "required": true, "options": ["Не запускается лаунчер", "Не скачиваются файлы игры", "Игра вылетает", "Не могу войти в аккаунт", "Ошибка в игре", "Другое"]}, {"key": "how", "label": "Как вы заходите в игру", "type": "radio", "required": true, "options": ["Через лаунчер World RP", "Клиентом SA-MP напрямую"]}, {"key": "problem", "label": "Кратко о проблеме", "type": "text", "required": true, "placeholder": "Например: вылет при входе на сервер", "max": 100}, {"key": "essence", "label": "Подробное описание", "type": "textarea", "required": true, "hint": "Когда началось, что именно происходит, текст ошибки, если есть."}, {"key": "system", "label": "Компьютер", "type": "text", "placeholder": "Windows 10, 8 ГБ памяти, видеокарта GTX 1050", "max": 150}, {"key": "tried", "label": "Что уже пробовали сделать", "type": "textarea"}, {"key": "proof", "label": "Скриншот или видео ошибки", "type": "url", "hint": "Загрузите скриншот на imgur.com или yapx.ru и вставьте ссылку."}]}', title_hint = 'Тип проблемы | Кратко о проблеме' WHERE id = 21;
-- Криминальных организаций в игре нет - раздел правил отдаём лидерам
UPDATE nodes SET title = 'Правила для лидеров и заместителей', icon = 'crown' WHERE id = 34 AND title = 'Правила криминальных организаций';
UPDATE nodes SET description = 'Правительство и Департамент полиции: устав, заявления, жалобы на сотрудников, законы' WHERE id = 56;
UPDATE nodes SET description = 'Помощь с лаунчером, игрой и ошибками мода, восстановление имущества' WHERE id = 20;
